const POLL_EVERY_MS = 3000;
const POLL_MAX = 20;
/* ★ FE35: حدّ جداري إجمالي للتحقق المحدود — 20×3s ليست دقيقة زمن حائط لأن
   الاستجابة نفسها تستغرق وقتاً. لا نعد المشتري بأي زمن؛ القرار داخلي فقط:
   عند الحد نتوقف بشاشة متابعة («الدفع قيد المراجعة») لا فشل دفع. */
