export function normStatus(v) { return normStatusOf(v); }
export const resolvePaymentOutcome = resolvePaymentOutcomeOf;
export function retryGate(fresh, nowMs, waitUntilMs) { return retryGateOf(fresh, nowMs, waitUntilMs); }


function attemptOrderId(st, pending) {
  const c = [st && st.orderId, st && st.order_id, st && st.orderID, st && st.data && st.data.orderId, pending && pending.orderId].filter(Boolean)[0];
  return Number(c) || 0;
}

/* ★ FE31: مدخلات قرار شاشة العودة — مُصدَّرة للاختبار (التعريف في orders.js). */
